// ---------------------------------------------------------------------------
// Monta o prompt do gerador de questões do BANCO.
//
// Diferente de `tino-questoes`, aqui não existe aula: o recorte é área,
// assunto e nível. Era exatamente por isso que o fluxo antigo respondia
// "O título da aula é obrigatório" para esta chamada.
// ---------------------------------------------------------------------------
const entrada = $input.first().json;
const b = entrada.body || entrada;

const area = String(b.area || '').trim();
const assunto = String(b.assunto || '').trim();

if (!area || !assunto) {
  throw new Error('Informe a área e o assunto para gerar as questões do banco.');
}

const nivel = String(b.nivel || 'Intermediário').trim();
const modo = b.modo === 'prova' ? 'prova' : 'ia';
const banca = String(b.banca || 'CFC (Exame de Suficiência) e concursos fiscais brasileiros').trim();
const observacoes = String(b.observacoes || '').trim();
const qtd = Math.min(Math.max(parseInt(b.quantidade, 10) || 5, 1), 15);
const anoAtual = new Date().getFullYear();

const calibragem = {
  'Iniciante':
    'Cobre definição, finalidade e o passo básico da rotina. O distrator deve ser um engano comum de quem está começando, nunca pegadinha de redação.',
  'Intermediário':
    'Cobre aplicação em situação concreta do escritório. Peça o porquê da decisão, não só o nome do conceito. O distrator deve ser plausível para quem sabe a teoria mas nunca executou.',
  'Avançado':
    'Cobre exceção, conflito de regra e consequência de escolher errado. O distrator deve ser a resposta certa em outro contexto — o que separa quem domina de quem decorou.',
};

const blocoProva = modo === 'prova'
  ? [
      '',
      'MODO PROVA ANTERIOR',
      'Escreva questões NO ESTILO das provas de ' + banca + '.',
      '',
      'Isto significa imitar o recorte, o vocabulário e o nível de cobrança dessas',
      'bancas — NÃO copiar enunciado de prova real. Escreva questão nova.',
      '',
      'Para cada questão preencha também:',
      '  "banca": nome da banca de referência (ex.: "CFC", "FGV", "CESPE/Cebraspe")',
      '  "ano":   ano de referência plausível, entre 2019 e ' + anoAtual,
      '  "prova": identificação da prova de referência (ex.: "Exame de Suficiência 2023.1")',
      '',
      'Não afirme que a questão caiu na prova: ela é inspirada no estilo dela.',
    ].join('\n')
  : [
      '',
      'MODO AUTORAL',
      'Questão nova, escrita para a realidade contábil brasileira de ' + anoAtual + ',',
      'incluindo a transição da Reforma Tributária quando o assunto pedir.',
    ].join('\n');

const system = [
  'Você monta o banco de questões da Castelo Branco Academy, escola de',
  'contabilidade da Castelo Branco Contabilidade Avançada (Feira de Santana/BA),',
  'especializada em tributário, transporte, logística e comércio exterior.',
  '',
  'Você responde SEMPRE com JSON válido, sem cerca de código e sem comentário.',
].join('\n');

const user = [
  'Gere exatamente ' + qtd + ' questões de múltipla escolha.',
  '',
  'ESCOPO',
  'Área: ' + area,
  'Assunto: ' + assunto,
  'Nível: ' + nivel,
  observacoes ? 'Instruções do administrador: ' + observacoes : null,
  '',
  'CALIBRAGEM PARA O NÍVEL ' + nivel.toUpperCase(),
  calibragem[nivel] || calibragem['Intermediário'],
  blocoProva,
  '',
  'REGRAS',
  '1. Quatro alternativas por questão, com ids "a", "b", "c" e "d".',
  '2. Uma única correta. Varie qual letra é a certa entre as questões.',
  '3. Alternativas de comprimento parecido. A mais longa não pode ser sempre a',
  '   correta — é o vício que ensina o aluno a chutar por formato.',
  '4. Nada de "todas as anteriores", "nenhuma das anteriores" ou negativa dupla.',
  '5. Enunciado direto, no máximo quatro linhas, em português brasileiro.',
  '6. A explicação diz por que a correta está certa E por que o erro mais provável',
  '   está errado. Duas a quatro linhas.',
  '7. Não invente número, prazo, alíquota ou artigo de lei de que não tenha',
  '   certeza. Prefira a formulação conceitual à numérica quando houver dúvida.',
  '8. As ' + qtd + ' questões precisam ser diferentes entre si — não reformule a',
  '   mesma ideia com outras palavras.',
  '',
  'Responda APENAS com este formato:',
  '{"questoes":[{"enunciado":"...","alternativas":[{"id":"a","texto":"..."},{"id":"b","texto":"..."},{"id":"c","texto":"..."},{"id":"d","texto":"..."}],"correta":"b","explicacao":"...","banca":"CFC","ano":2023,"prova":"Exame de Suficiência 2023.1"}]}',
].filter(function (l) { return l !== null; }).join('\n');

return [{ json: { system: system, user: user, qtd: qtd, area: area, assunto: assunto, nivel: nivel, modo: modo, banca: banca } }];

// ---------------------------------------------------------------------------
// Aceita só o que dá para publicar.
//
// Questão sem gabarito válido é pior que questão nenhuma: o administrador não
// perceberia, e o aluno estudaria a resposta errada.
// ---------------------------------------------------------------------------
const bruto = $input.first().json;
const meta = $('Montar prompt').first().json;

let texto = '';
if (bruto && Array.isArray(bruto.content)) {
  texto = bruto.content.map(function (c) { return c.text || ''; }).join('\n');
} else if (typeof bruto === 'string') {
  texto = bruto;
} else if (bruto && typeof bruto.resposta === 'string') {
  texto = bruto.resposta;
} else {
  texto = JSON.stringify(bruto);
}

function extrairJSON(t) {
  const limpo = String(t).replace(/```(?:json)?/gi, '').trim();
  try {
    return JSON.parse(limpo);
  } catch (e) {
    const i = limpo.indexOf('{');
    const f = limpo.lastIndexOf('}');
    if (i === -1 || f <= i) return null;
    try {
      return JSON.parse(limpo.slice(i, f + 1));
    } catch (e2) {
      return null;
    }
  }
}

const dados = extrairJSON(texto);
const lista = Array.isArray(dados) ? dados : (dados && dados.questoes) || [];
const LETRAS = ['a', 'b', 'c', 'd'];
const ok = [];

for (const item of lista) {
  if (!item || typeof item.enunciado !== 'string') continue;
  const enunciado = item.enunciado.trim();
  if (!enunciado) continue;

  const brutas = Array.isArray(item.alternativas) ? item.alternativas : [];
  const alternativas = [];
  brutas.slice(0, 4).forEach(function (a, i) {
    const t = typeof a === 'string' ? a : (a && typeof a.texto === 'string' ? a.texto : '');
    const idBruto = a && typeof a.id === 'string' ? a.id.toLowerCase() : '';
    const id = LETRAS.indexOf(idBruto) >= 0 ? idBruto : LETRAS[i];
    if (t && t.trim()) alternativas.push({ id: id, texto: t.trim() });
  });
  if (alternativas.length < 2) continue;

  const correta = typeof item.correta === 'string' ? item.correta.trim().toLowerCase() : '';
  if (!alternativas.some(function (a) { return a.id === correta; })) continue;

  const ano = parseInt(item.ano, 10);
  ok.push({
    enunciado: enunciado,
    alternativas: alternativas,
    correta: correta,
    explicacao: typeof item.explicacao === 'string' ? item.explicacao.trim() : undefined,
    banca: meta.modo === 'prova' && typeof item.banca === 'string' ? item.banca.trim() : undefined,
    ano: meta.modo === 'prova' && ano > 1990 && ano < 2100 ? ano : undefined,
    prova: meta.modo === 'prova' && typeof item.prova === 'string' ? item.prova.trim() : undefined,
  });
}

if (ok.length === 0) {
  throw new Error('O modelo não devolveu nenhuma questão válida. Confira a chave da Anthropic e tente de novo.');
}

return [{
  json: {
    questoes: ok.slice(0, meta.qtd),
    fonte: 'n8n',
    area: meta.area,
    assunto: meta.assunto,
    nivel: meta.nivel,
    modo: meta.modo,
  },
}];
